using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;using Newtonsoft.Json;
public static class B4Play {
 static MonoBehaviour look;static bool lookEnabled,previousCulling;static Transform pivot;static Quaternion previousPivot;static Camera testCamera;static Mouse mouse;static bool mouseWasEnabled;static double start;static int firstFrame,lastFrame;static GameObject player;static Vector3 from;static Keyboard keyboard;static bool released,keyboardWasEnabled;static string label;static float hold;static List<float> frameTimes=new List<float>();static List<object> errors=new List<object>();static InputSettings.BackgroundBehavior background;static InputSettings.EditorInputBehaviorInPlayMode editorBehavior;
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_B4_Observation/"));
