 static object Start(string id,Vector3 p,float yaw,float seconds){if(!Application.isPlaying)throw new Exception("Play required");if(!SceneManager.GetActiveScene().path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 required");hold=seconds;mouse=Mouse.current;mouseWasEnabled=mouse!=null&&mouse.enabled;if(mouseWasEnabled)InputSystem.DisableDevice(mouse);label=id;frameTimes.Clear();errors.Clear();player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));look=player.GetComponentsInChildren<MonoBehaviour>(true).Single(c=>c.GetType().Name=="PlayerLook");lookEnabled=look.enabled;look.enabled=false;pivot=(Transform)look.GetType().GetField("cameraRoot",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(look);previousPivot=pivot.localRotation;pivot.localRotation=Quaternion.identity;testCamera=Camera.main;previousCulling=testCamera.useOcclusionCulling;testCamera.useOcclusionCulling=false;var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.SetPositionAndRotation(p,Quaternion.Euler(0,yaw,0));cc.enabled=true;Physics.SyncTransforms();from=p;firstFrame=lastFrame=Time.frameCount;start=EditorApplication.timeSinceStartup;released=false;
 editorBehavior=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;var view=typeof(Editor).Assembly.GetType("UnityEditor.GameView");EditorWindow.GetWindow(view).Focus();background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=Keyboard.current;if(keyboard==null)throw new Exception("No keyboard");keyboardWasEnabled=keyboard.enabled;if(!keyboardWasEnabled)InputSystem.EnableDevice(keyboard);InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));Application.logMessageReceived+=Log;EditorApplication.update+=Tick;return new{id,frame=firstFrame,hold,from=from.ToString()};}
