 static void Tick(){if(!Application.isPlaying){End(false);return;}EditorApplication.QueuePlayerLoopUpdate();double elapsed=EditorApplication.timeSinceStartup-start;if(Time.frameCount!=lastFrame){lastFrame=Time.frameCount;if(elapsed>1.5)frameTimes.Add(Time.unscaledDeltaTime*1000);}if(elapsed<hold)InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));if(!released&&elapsed>hold){InputSystem.QueueStateEvent(keyboard,new KeyboardState());released=true;}if(elapsed>8)End(true);}
